CREATE TABLE IF NOT EXISTS `projects` (`id` INTEGER NOT NULL, `name` TEXT NOT NULL, `hfSourceRepo` TEXT NOT NULL, `hfDestRepo` TEXT NOT NULL, `sourceConfig` TEXT NOT NULL, `sourceSplit` TEXT NOT NULL, `imageColumn` TEXT NOT NULL, `idColumn` TEXT NOT NULL, `targetSplit` TEXT NOT NULL, `activeTasksCsv` TEXT NOT NULL, `classesCsv` TEXT NOT NULL, `diskBudgetMb` INTEGER NOT NULL, `modelPath` TEXT, `modelConfigJson` TEXT, `prefetchEnabled` INTEGER NOT NULL, `settingsJson` TEXT NOT NULL DEFAULT '{}', `lastRowCursor` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`id`));

CREATE TABLE IF NOT EXISTS `batches` (`projectId` INTEGER NOT NULL, `batchNumber` INTEGER NOT NULL, `status` TEXT NOT NULL, `totalCases` INTEGER NOT NULL, `validatedCases` INTEGER NOT NULL, `rejectedCases` INTEGER NOT NULL, `deferredCases` INTEGER NOT NULL, `hfCommitSha` TEXT, `archivePath` TEXT, `archiveSnapshot` TEXT, `verifiedArchiveUri` TEXT, `verifiedArchiveSha256` TEXT, `verificationKind` TEXT, `remotePrefix` TEXT, `remoteBranch` TEXT, `remoteRepoId` TEXT, `remoteParentCommit` TEXT, `preparedManifestSha256` TEXT, `lastTransferError` TEXT, `remoteReceiptJson` TEXT, `archiveSizeBytes` INTEGER, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`projectId`, `batchNumber`));

CREATE TABLE IF NOT EXISTS `samples` (`sampleId` TEXT NOT NULL, `projectId` INTEGER NOT NULL, `batchNumber` INTEGER NOT NULL, `assetId` TEXT NOT NULL, `sourceRowIndex` INTEGER NOT NULL, `sourceOrdinal` INTEGER, `sourceFileUrl` TEXT, `localImagePath` TEXT, `imageWidth` INTEGER NOT NULL, `imageHeight` INTEGER NOT NULL, `sha256` TEXT, `phash` INTEGER, `sourceSha256` TEXT, `imageTransform` TEXT NOT NULL DEFAULT 'identity', `groupId` TEXT, `split` TEXT NOT NULL, `acquisitionStatus` TEXT NOT NULL, `annotationStatus` TEXT NOT NULL, `syncStatus` TEXT NOT NULL, `auditReason` TEXT, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`sampleId`));
CREATE INDEX IF NOT EXISTS `index_samples_projectId_batchNumber_sourceOrdinal` ON `samples` (`projectId`, `batchNumber`, `sourceOrdinal`);
CREATE INDEX IF NOT EXISTS `index_samples_projectId_annotationStatus` ON `samples` (`projectId`, `annotationStatus`);
CREATE INDEX IF NOT EXISTS `index_samples_projectId_sha256` ON `samples` (`projectId`, `sha256`);
CREATE TABLE IF NOT EXISTS `annotations` (`sampleId` TEXT NOT NULL, `dataJson` TEXT NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`sampleId`));

CREATE TABLE IF NOT EXISTS `audit_logs` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `sampleId` TEXT, `batchNumber` INTEGER NOT NULL, `action` TEXT NOT NULL, `details` TEXT NOT NULL, `projectId` INTEGER NOT NULL DEFAULT 1, `timestamp` INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS `index_audit_logs_projectId_timestamp` ON `audit_logs` (`projectId`, `timestamp`);
CREATE TABLE IF NOT EXISTS `source_entries` (`projectId` INTEGER NOT NULL, `ordinal` INTEGER NOT NULL, `assetId` TEXT NOT NULL, `imageRef` TEXT NOT NULL, `sourceRowIndex` INTEGER, `groupId` TEXT, `annotationJson` TEXT, PRIMARY KEY(`projectId`, `ordinal`));

CREATE TABLE IF NOT EXISTS `model_profiles` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `modelPath` TEXT NOT NULL, `sha256` TEXT NOT NULL, `configJson` TEXT NOT NULL, `tensorReport` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
